// PRIVATE fixed-fixture owner assembly. Caller approval/clock/admission remain
// explicitly trusted inputs, not authentication or machine-capacity evidence.
// No discovery, build, install, retry, delete, resume or implicit model selection.
import fs from 'node:fs';
import path from 'node:path';
import {types} from 'node:util';
import {fileURLToPath} from 'node:url';
import {record} from '../../evaluation/intake-v1.mjs';
import {cloneFreeze,stableStringify,sha256Text} from '../../workflow/contracts.mjs';
import {readPreventionExperimentPlanV1} from '../../evaluation/prevention-experiment-plan-v1.mjs';
import {readPreventionExecutionProfileV1} from '../../evaluation/prevention-execution-profile-v1.mjs';
import {readScheduledPairedTrialIntentV1} from '../../evaluation/paired-trial-runner-v1.mjs';
import {readIssuedRepositoryOracleV1} from '../../examples/repository-task/reviewed-oracle-fixture-v1.mjs';
import {readLiveModelSelectionV3} from './live-model-selection-v3.mjs';
import {createReviewedLiveModelLaneV4,readIssuedLiveModelLaneV4} from './reviewed-live-model-v4.mjs';
import {describePlannedRepositoryTrialInputsV2,checkRepositoryTrialIntentV2} from './paired-trial-projection-v2.mjs';
import {createReviewedRepositoryHostV1,readIssuedRepositoryWorkflowIdentityV1} from './reviewed-workflow-v1.mjs';
import {createRepositoryTrialOracleV1,readIssuedRepositoryTrialOracleV1} from './paired-trial-oracle-v1.mjs';
import {isIssuedNativeArtifactBuild} from '../swift-verifier/build.mjs';
import {resolveExternalDemoStateV1,recheckExternalDemoStateV1} from './demo-state-v1.mjs';
import {createPairedArmCommandOwnerV1} from '../../cli/paired-arm-command-owner.mjs';
import {inspectArmTrialDirectoryV1} from '../../cli/paired-arm-inspect.mjs';

const sourceRoot=fileURLToPath(new URL('../../',import.meta.url));
const fail=code=>{throw Object.assign(Error(code),{code});};
const hash=(domain,value)=>sha256Text(domain+'\0'+stableStringify(value));
const exact=(value,keys)=>{if(types.isProxy(value))fail('ARM_BOOTSTRAP_SCHEMA');return record(value,keys);};
// Factories are synchronous. Observe rejected native promises without awaiting
// them or using their late values; never retry uncertain construction.
const synchronous=value=>{
  if(types.isPromise(value)){
    Promise.prototype.then.call(value,()=>{},()=>{});
    fail('ARM_BOOTSTRAP_ASYNC_DEPENDENCY');
  }
  return value;
};
const bounds=(raw,limits)=>{
  const value=cloneFreeze(exact(raw,Object.keys(limits)));
  for(const [key,max] of Object.entries(limits))
    if(!Number.isSafeInteger(value[key])||value[key]<1||value[key]>max)fail('ARM_BOOTSTRAP_BUDGET');
  return value;
};
function budgets(raw){
  const b=exact(raw,['model','host','oracle']);
  const model=bounds(b.model,{timeoutMs:90000,maxOutputTokens:4096});
  const host=bounds(b.host,{staticTimeoutMs:60000,totalTestTimeoutMs:60000,testTimeoutMs:60000,
    closeGraceMs:2000,materializationTimeoutMs:60000});
  const oracle=bounds(b.oracle,{materializationTimeoutMs:60000,totalTimeoutMs:60000,childTimeoutMs:60000,closeGraceMs:2000});
  if(host.testTimeoutMs>host.totalTestTimeoutMs||oracle.childTimeoutMs>oracle.totalTimeoutMs)fail('ARM_BOOTSTRAP_BUDGET');
  return Object.freeze({model,host,oracle});
}
// Descriptive digests only. The production constructor separately requires an
// original process-issued build; data or these digests cannot issue a build.
export function describeReviewedPairedArmEnvironmentV1(input){
  const x=exact(input,['build','budgets']);
  if(types.isProxy(x.build))fail('ARM_BOOTSTRAP_BUILD');
  return cloneFreeze({toolchainSha256:hash('nisi/paired-arm-build/v1',cloneFreeze(x.build)),
    resourceBudgetSha256:hash('nisi/paired-arm-resources/v1',budgets(x.budgets)),authorizing:false});
}
const production=Object.freeze({checkBuild(build,root){
  if(!isIssuedNativeArtifactBuild(build)||build.schemaVersion!==2||build.stateRoot!==root.directory||
    build.stateRootDev!==root.dev||build.stateRootIno!==root.ino)fail('ARM_BOOTSTRAP_BUILD');
},createHost:createReviewedRepositoryHostV1,createLane:createReviewedLiveModelLaneV4,
createOracle:createRepositoryTrialOracleV1,signalSource:process});

export function createReviewedPairedArmBootstrapV1(input){return make(input,production,'LOOPBACK_HTTP');}
// Trusted test factories cannot establish native/provider authenticity. The
// distinct transport kind is bound into the profile and all resulting receipts.
export function createReviewedPairedArmBootstrapWithDependenciesV1(input,dependencies){
  return make(input,dependencies,'INJECTED_TEST_TRANSPORT');
}
function make(input,dependencies,transportKind){
  const x=exact(input,['plan','profile','approval','now','observe','registration','build','selection','treatments','budgets','stateDirectory']);
  const deps=exact(dependencies,['checkBuild','createHost','createLane','createOracle','signalSource']);
  for(const name of ['checkBuild','createHost','createLane','createOracle'])if(typeof deps[name]!=='function')fail('ARM_BOOTSTRAP_DEPENDENCY');
  const signalSource=Object.freeze(Object.fromEntries(['on','removeListener','rawListeners'].map(name=>{
    const fn=deps.signalSource?.[name];if(typeof fn!=='function')fail('ARM_BOOTSTRAP_SIGNALS');
    return [name,fn.bind(deps.signalSource)];
  })));
  if(typeof x.now!=='function'||typeof x.observe!=='function')fail('ARM_BOOTSTRAP_CALLBACK');
  const now=x.now,observe=x.observe,rawPlan=cloneFreeze(x.plan),rawProfile=cloneFreeze(x.profile);
  const plan=readPreventionExperimentPlanV1(rawPlan),profile=readPreventionExecutionProfileV1(rawProfile,plan.planSha256,plan.policy);
  const approval=cloneFreeze(exact(x.approval,['id','ownerId','planSha256','profileSha256','expiresAtMs','priority']));
  if(![approval.id,approval.ownerId].every(v=>typeof v==='string'&&/^[a-z][a-z0-9_.-]{0,95}$/u.exec(v)?.[0]===v)||
    approval.planSha256!==plan.planSha256||approval.profileSha256!==profile.profileSha256||
    !Number.isSafeInteger(approval.expiresAtMs)||approval.expiresAtMs<1||!['FOREGROUND','BACKGROUND'].includes(approval.priority))
    fail('ARM_BOOTSTRAP_APPROVAL');
  const registration=x.registration,owned=readIssuedRepositoryOracleV1(registration),fixture=owned.workflow;
  const selected=readLiveModelSelectionV3(x.selection),treatments=Object.freeze(exact(x.treatments,['OFF','ON'])),b=budgets(x.budgets);
  const build=x.build,environment=describeReviewedPairedArmEnvironmentV1({build,budgets:b});
  if(profile.toolchainSha256!==environment.toolchainSha256||profile.resourceBudgetSha256!==environment.resourceBudgetSha256)
    fail('ARM_BOOTSTRAP_ENVIRONMENT');
  const expectedArms=plan.tasks.length*plan.repetitions*2;
  if(expectedArms>256||plan.tasks.some(task=>['taskSha256','baselineSha256'].some(k=>task[k]!==registration.workflow[k])||
    task.oracleSha256!==registration.oracleSha256))fail('ARM_BOOTSTRAP_POPULATION');
  const laneInput=arm=>Object.freeze({suite:fixture.suite,reviewedSourceFingerprint:fixture.reviewedSourceFingerprint,
    ...selected,...b.model,approval:Object.freeze({id:approval.id,expiresAtMs:approval.expiresAtMs}),arm,treatment:treatments[arm]});
  for(const arm of ['OFF','ON']){
    const description=describePlannedRepositoryTrialInputsV2(laneInput(arm),transportKind);
    if(profile.model!==description.model||profile.modelSettingsSha256!==description.modelSettingsSha256||
      profile.trialPolicy.version!==description.configuration.policy.version||profile.trialPolicy.sha256!==description.guidancePolicySha256)
      fail('ARM_BOOTSTRAP_MODEL_PROFILE');
  }
  // Last preflight reads only the explicit existing private directory. No build,
  // directory creation, transport owner or command listener has been started.
  const root=resolveExternalDemoStateV1(x.stateDirectory,sourceRoot);
  if(synchronous(deps.checkBuild(build,root))!==undefined)fail('ARM_BOOTSTRAP_BUILD');
  const schedule=Array.from({length:plan.repetitions},(_,repetition)=>plan.tasks.flatMap(task=>
    task.armOrder[repetition].split('_').map(arm=>({caseId:task.caseId,repetition,arm})))).flat();
  let state='READY',reason=null,command=null,report=null,session=null,cursor=0,runnerId=null;
  let cleanup='NOT_STARTED',setupStop=false,attempts=0,lanesClosed=0,lanesCleanupUnconfirmed=0;
  let constructionCleanupUnconfirmed=false;
  const lanes=[],reservations=new Set();
  function construct(factory,options,validate=()=>{}){
    try{const value=synchronous(factory(options));validate(value);return value;}
    catch(error){
      // A throwing/async factory returned no inspectable owner. Even if its
      // internal rollback succeeded, this outer layer cannot attest that fact.
      constructionCleanupUnconfirmed=true;throw error;
    }
  }
  function reserve(intent){
    if(state!=='RUNNING'||reason)fail('ARM_BOOTSTRAP_NOT_RUNNING');
    const issued=readScheduledPairedTrialIntentV1(intent),expected=schedule[cursor];
    if(issued.plan.planSha256!==plan.planSha256||issued.profile.profileSha256!==profile.profileSha256||
      (runnerId!==null&&runnerId!==intent.runnerId)||!expected||
      Object.keys(expected).some(k=>expected[k]!==intent[k])||reservations.has(intent.requestId))fail('ARM_BOOTSTRAP_INTENT');
    runnerId??=intent.runnerId;reservations.add(intent.requestId);const ordinal=cursor++;attempts++;
    try{
      recheckExternalDemoStateV1(root,sourceRoot);
      const workspaceParentRoot=path.join(session,'workspace-'+ordinal),oracleParentRoot=path.join(session,'oracle-'+ordinal);
      fs.mkdirSync(workspaceParentRoot,{mode:0o700});fs.mkdirSync(oracleParentRoot,{mode:0o700});
      const host=construct(deps.createHost,{suite:fixture.suite,build,scope:'operator-exclusive-static-local-v1',targets:fixture.targets,
        parentRoot:workspaceParentRoot,...b.host},readIssuedRepositoryWorkflowIdentityV1);
      const oracle=construct(deps.createOracle,{registration,binding:{...registration.workflow,requestId:intent.requestId,
        profileSha256:profile.profileSha256,oracleSha256:registration.oracleSha256},parentRoot:oracleParentRoot,...b.oracle},readIssuedRepositoryTrialOracleV1);
      const lane=construct(deps.createLane,laneInput(intent.arm));
      // Own the lane before any later fallible check. Downstream admission can
      // still refuse; final cleanup will close this unused original lane.
      lanes.push(lane);checkRepositoryTrialIntentV2(intent,lane);
      return Object.freeze({host,lane,oracle});
    }catch(error){reason??=error?.code==='ARM_BOOTSTRAP_ASYNC_DEPENDENCY'?error.code:'ARM_BOOTSTRAP_RESERVATION_FAILED';
      throw Object.assign(Error(reason),{code:reason});}
  }
  function closeLanes(){
    cleanup='CONFIRMED';
    for(const lane of lanes){
      try{
        let snapshot=readIssuedLiveModelLaneV4(lane).snapshot;
        if(!snapshot.revoked){lane.revoke();snapshot=readIssuedLiveModelLaneV4(lane).snapshot;}
        if(!snapshot.revoked||snapshot.lifecycle.state!=='STOPPED'||snapshot.lifecycle.pendingTransports!==0||snapshot.lifecycle.recoveryRequired)
          lanesCleanupUnconfirmed++;
        else lanesClosed++;
      }catch{lanesCleanupUnconfirmed++;}
    }
    if(lanesCleanupUnconfirmed||constructionCleanupUnconfirmed)cleanup='UNCONFIRMED';
  }
  function inspect(...args){
    if(args.length)fail('ARM_BOOTSTRAP_ARGUMENTS');
    return cloneFreeze({schemaVersion:'nisi-reviewed-paired-arm-bootstrap-v1',state,reason,transportKind,
      expectedArms,reservationAttempts:attempts,lanesCreated:lanes.length,lanesClosed,lanesCleanupUnconfirmed,
      constructionCleanupUnconfirmed,cleanup,command:report,
      recorded:report?.recorded===true&&reason===null&&cleanup==='CONFIRMED',
      authorizing:false,resumable:false,measurementVerified:false,causalClaim:false,promotionEligible:false,
      actualDispatchCount:null,remoteExecutionStopped:'UNKNOWN'});
  }
  function requestStop(...args){
    if(args.length)fail('ARM_BOOTSTRAP_ARGUMENTS');
    if(state!=='RUNNING')return Object.freeze({status:'REFUSED',reason:'ARM_BOOTSTRAP_NOT_RUNNING',authorizing:false});
    if(command)return command.requestStop();
    const status=setupStop?'ALREADY_REQUESTED':'REQUESTED';setupStop=true;return Object.freeze({status,authorizing:false});
  }
  async function run(...args){
    if(args.length||state!=='READY')fail('ARM_BOOTSTRAP_ALREADY_RAN');
    state='RUNNING';
    try{
      const directory=recheckExternalDemoStateV1(root,sourceRoot);
      if(stableStringify(describeReviewedPairedArmEnvironmentV1({build,budgets:b}))!==stableStringify(environment))
        fail('ARM_BOOTSTRAP_ENVIRONMENT');
      session=fs.mkdtempSync(path.join(directory,'paired-arm-'));
      command=createPairedArmCommandOwnerV1({plan:rawPlan,profile:rawProfile,approval,now,observe,reserve,parentDirectory:session},
        {signalSource,mainIo:fs,sidecarIo:fs,inspectDirectory:inspectArmTrialDirectoryV1});
      const running=command.run();if(setupStop)command.requestStop();report=await running;
    }catch{reason??='ARM_BOOTSTRAP_SETUP_OR_RUN_FAILED';}
    finally{closeLanes();state='FINISHED';}
    return inspect();
  }
  return Object.freeze({run,requestStop,inspect});
}

// PRIVATE V4 experimental guidance lane. Same candidate population for OFF/ON.
// Returned unregistered source is retained data, never execution approval.
import { createLocalChatGuidedAuthorAdapterV1, createLocalChatReviewerAdapter, createLocalChatTransportOwner } from '../../adapters/local-chat.mjs';
import { createNativeChatGuidedAuthorAdapterV1, createNativeChatReviewerAdapterV1, createNativeChatTransportOwnerV1 } from '../../adapters/native-chat-v1.mjs';
import { readRepairGuidanceV1 } from '../../adapters/repair-guidance-v1.mjs';
import { cloneFreeze, stableStringify, sha256Text, createCandidate, createTaskSpecification } from '../../workflow/contracts.mjs';
import { exact } from '../../integrity/record-utils.mjs';
import { reviewedNodePreparationsV1 } from './node-suite-v1.mjs';
import { readLiveModelSelectionV3 } from './live-model-selection-v3.mjs';
import { liveModelOwnerStatusV1 } from './live-owner-status-v1.mjs';

const lanes = new WeakMap(), hash = (domain, value) => sha256Text(domain + '\0' + stableStringify(value));
const fail = code => { throw Object.assign(new Error(code), { code }); };
const isHash = v => typeof v === 'string' && /^[a-f0-9]{64}$/u.exec(v)?.[0] === v;
const errorCode = e => typeof e?.code === 'string' && /^[A-Z][A-Z0-9_]{0,95}$/u.exec(e.code)?.[0] === e.code ? e.code : 'LIVE_MODEL_ERROR';
const roleConfig = (role, guided = false) => ({ ...role, ...(role.api === 'NATIVE_API'
  ? { adapterReceiptVersion: guided ? 'nisi-native-chat-guidance-receipt-v1' : 'nisi-native-chat-receipt-v1', storeRequested: false, integrationsRequested: [] }
  : { adapterReceiptVersion: guided ? 4 : 2 }) });

export function createReviewedLiveModelLaneV4(input) {
  const transport = globalThis.fetch;
  return make(input, { author: transport, reviewer: transport }, Date.now, 'LOOPBACK_HTTP');
}
export function createReviewedLiveModelLaneWithTransportV4(input, transports, now = Date.now) {
  return make(input, transports, now, 'INJECTED_TEST_TRANSPORT');
}
// Pure preflight: preserve original fixture/treatment identities without creating
// transport owners, adapters, listeners or model requests.
export function prepareReviewedLiveModelLaneV4(input, transportKind = 'LOOPBACK_HTTP') {
  if (!['LOOPBACK_HTTP', 'INJECTED_TEST_TRANSPORT'].includes(transportKind)) fail('LIVE_TRANSPORT_KIND');
  exact(input, ['suite', 'reviewedSourceFingerprint', 'author', 'reviewer', 'timeoutMs', 'maxOutputTokens', 'approval', 'arm', 'treatment'], 'LIVE_LANE_SCHEMA');
  const suite = input.suite;
  const selection = readLiveModelSelectionV3({ author: input.author, reviewer: input.reviewer });
  const treatment = readRepairGuidanceV1(input.treatment, selection.author.api);
  if (input.arm !== treatment.arm) fail('LIVE_TREATMENT_ARM');
  const captured = cloneFreeze({ reviewedSourceFingerprint: input.reviewedSourceFingerprint,
    timeoutMs: input.timeoutMs, maxOutputTokens: input.maxOutputTokens, approval: input.approval });
  exact(captured.approval, ['id', 'expiresAtMs'], 'LIVE_APPROVAL_SCHEMA');
  if (typeof captured.approval.id !== 'string' || !/^[a-z][a-z0-9_.-]{0,95}$/u.test(captured.approval.id) ||
      !Number.isSafeInteger(captured.approval.expiresAtMs) || captured.approval.expiresAtMs <= 0) fail('LIVE_APPROVAL_INVALID');
  if (!isHash(captured.reviewedSourceFingerprint)) fail('LIVE_SOURCE_IDENTITY');
  if (!Number.isSafeInteger(captured.timeoutMs) || captured.timeoutMs < 1 || captured.timeoutMs > 90000 ||
      !Number.isSafeInteger(captured.maxOutputTokens) || captured.maxOutputTokens < 1 || captured.maxOutputTokens > 4096) fail('LIVE_CALL_BUDGET');
  const preparations = reviewedNodePreparationsV1(suite);
  if (preparations.length !== 2 || preparations[0].candidateFingerprint === preparations[1].candidateFingerprint) fail('LIVE_FIXTURE_PAIR');
  const [baseline, repaired] = preparations, task = baseline.task;
  if (task.mode !== 'edit' || task.policy.repairBudget !== 1 || task.policy.requiredReviewers !== 1) fail('LIVE_TASK_POLICY');
  const treatmentBinding = { taskFingerprint: baseline.taskFingerprint, baselineFingerprint: baseline.baselineFingerprint,
    suiteFingerprint: suite.fingerprint, reviewedSourceFingerprint: captured.reviewedSourceFingerprint };
  if (stableStringify(treatment.binding) !== stableStringify(treatmentBinding)) fail('LIVE_TREATMENT_BINDING');
  const configuration = cloneFreeze({ author: roleConfig(selection.author, true), reviewer: roleConfig(selection.reviewer),
    treatment, arm: treatment.arm,
    timeoutMs: captured.timeoutMs, maxOutputTokens: captured.maxOutputTokens, taskFingerprint: baseline.taskFingerprint,
    suiteFingerprint: suite.fingerprint, reviewedSourceFingerprint: captured.reviewedSourceFingerprint, transportKind,
    authorId: 'author.live-model', reviewerId: 'reviewer.live-model', maxRequestBytes: 262144, maxResponseBytes: 262144 });
  return Object.freeze({ suite, selection, treatment, captured, preparations, baseline, repaired, configuration });
}
function make(input, transports, now, transportKind) {
  const { suite, treatment, captured, preparations, baseline, repaired, configuration } = prepareReviewedLiveModelLaneV4(input, transportKind);
  exact(transports, ['author', 'reviewer'], 'LIVE_TRANSPORT_REQUIRED');
  if (typeof transports.author !== 'function' || typeof transports.reviewer !== 'function' || typeof now !== 'function') fail('LIVE_TRANSPORT_REQUIRED');
  const fetches = { author: transports.author, reviewer: transports.reviewer }, task = baseline.task;
  const configurationFingerprint = hash('nisi/live-model-configuration/v4', configuration);
  const approval = cloneFreeze({ ...captured.approval, scope: 'REVIEWED_FIXTURE_REPAIR_AND_REVIEW_ONLY', configurationFingerprint });
  const approvalFingerprint = hash('nisi/live-model-approval/v4', approval);
  const owners = {}, adapters = {}, invocations = [], requestObservations = [], pendingInvocations = new Map();
  // Memory-only original request channel. At most one request for each role;
  // ordinary snapshots/serialized receipts deliberately do not contain bodies.
  const observeTransport = role => function (url, request) {
    const invocation = pendingInvocations.get(role);
    if (!invocation || requestObservations.some(item => item.role === role)) fail('LIVE_REQUEST_INVENTORY');
    pendingInvocations.delete(role);
    exact(request, ['method', 'redirect', 'signal', 'headers', 'body'], 'LIVE_REQUEST_SCHEMA');
    if (typeof url !== 'string' || typeof request.body !== 'string' ||
        !(request.signal instanceof AbortSignal) || Buffer.byteLength(request.body, 'utf8') > configuration.maxRequestBytes)
      fail('LIVE_REQUEST_SCHEMA');
    if (Buffer.byteLength(JSON.stringify(invocation.payload), 'utf8') > configuration.maxRequestBytes + 1024) fail('LIVE_REQUEST_PAYLOAD_CAP');
    const captured = cloneFreeze({ method: request.method, redirect: request.redirect, headers: request.headers, body: request.body });
    // Pass exactly the frozen bytes/controls observed here and the original
    // signal once. Invocation is not proof of provider delivery or execution.
    invocations[invocation.index] = Object.freeze({ role, operation: invocation.operation,
      binding: invocation.payload.binding, payload: invocation.payload });
    requestObservations.push(cloneFreeze({ role, api: configuration[role].api, operation: invocation.operation,
      endpoint: url, request: captured, requestBytes: Buffer.byteLength(captured.body, 'utf8'),
      requestSha256: sha256Text(captured.body), binding: invocation.payload.binding,
      observation: 'LOCAL_TRANSPORT_INVOKED', providerDeliveryAttested: false }));
    return Reflect.apply(fetches[role], this, [url, Object.freeze({ ...captured, signal: request.signal })]);
  };
  try {
    for (const name of ['author', 'reviewer']) {
      const r = configuration[name], native = r.api === 'NATIVE_API';
      const owner = native ? createNativeChatTransportOwnerV1() : createLocalChatTransportOwner(); owners[name] = owner;
      const common = { destination: 'LOOPBACK_HTTP', endpoint: r.endpoint, model: r.model, id: configuration[name + 'Id'],
        timeoutMs: configuration.timeoutMs, maxOutputTokens: configuration.maxOutputTokens,
        maxRequestBytes: configuration.maxRequestBytes, maxResponseBytes: configuration.maxResponseBytes,
        transportOwner: owner, fetch: observeTransport(name) };
      const options = native ? { ...common, expectedModelInstance: r.expectedModelInstance, reasoning: r.reasoning }
        : { ...common, outputMode: r.outputMode };
      adapters[name] = name === 'author'
        ? (native ? createNativeChatGuidedAuthorAdapterV1 : createLocalChatGuidedAuthorAdapterV1)(options, treatment)
        : (native ? createNativeChatReviewerAdapterV1 : createLocalChatReviewerAdapter)(options);
    }
  } catch (error) {
    // Constructor failure returns no lane handle. Stop every owner allocated
    // so far here. An unconfirmed rollback takes precedence over the original
    // error; callers cannot claim cleanup of an owner they never received.
    let confirmed = true;
    for (const owner of Object.values(owners)) {
      try {
        owner.stop();
        const status = owner.status();
        if (status.state !== 'STOPPED' || status.pendingTransports !== 0 || status.recoveryRequired) confirmed = false;
      } catch { confirmed = false; }
    }
    if (!confirmed) fail('LIVE_CONSTRUCTOR_ROLLBACK_UNCONFIRMED');
    throw error;
  }
  let phase = 'NEW', runId = null, revoked = false, lastWall = null;
  const events = [], returnedResults = [], stopOwners = () => { owners.author.stop(); owners.reviewer.stop(); };
  function lifecycle() {
    const roles = { author: owners.author.status(), reviewer: owners.reviewer.status() }, values = Object.values(roles);
    const pendingTransports = values.reduce((n, s) => n + s.pendingTransports, 0);
    const recoveryRequired = values.some(s => s.recoveryRequired);
    const state = recoveryRequired ? 'QUARANTINED' : values.some(s => ['DRAINING', 'STOPPED_DRAINING'].includes(s.state)) ? 'DRAINING'
      : values.some(s => s.state === 'BUSY') ? 'BUSY' : values.some(s => s.state === 'STOPPED') ? 'STOPPED' : 'IDLE';
    return cloneFreeze({ state, pendingTransports, recoveryRequired, remoteInferenceStopped: 'NOT_OBSERVED', scope: 'THIS_LANE_ONLY', roles });
  }
  function snapshotPayload(raw) {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw) || ![Object.prototype, null].includes(Object.getPrototypeOf(raw))) fail('LIVE_PAYLOAD_SCHEMA');
    const descriptors = Object.getOwnPropertyDescriptors(raw), data = {};
    for (const key of Reflect.ownKeys(descriptors)) {
      if (!['task', 'candidate', 'acceptanceCriteria', 'binding', 'signal', 'checks', 'tests', 'stages', 'reviewerId'].includes(key) ||
          !Object.hasOwn(descriptors[key], 'value') || !descriptors[key].enumerable) fail('LIVE_PAYLOAD_SCHEMA');
      if (key !== 'signal') data[key] = descriptors[key].value;
    }
    const signal = descriptors.signal?.value;
    if (signal !== undefined && !(signal instanceof AbortSignal)) fail('LIVE_SIGNAL_INVALID');
    return Object.freeze({ ...cloneFreeze(data), ...(signal !== undefined ? { signal } : {}) });
  }
  function scopeGuard(p) {
    const wall = now();
    if (!Number.isSafeInteger(wall) || wall < 0 || (lastWall !== null && wall < lastWall)) { stopOwners(); fail('LIVE_CLOCK_INVALID'); }
    lastWall = wall;
    if (revoked) fail('LIVE_APPROVAL_REVOKED');
    if (wall >= approval.expiresAtMs) { stopOwners(); fail('LIVE_APPROVAL_EXPIRED'); }
    if (p.signal?.aborted) { stopOwners(); fail('ABORTED'); }
  }
  function guard(p, expectedPhase, attempt, candidateFingerprint) {
    scopeGuard(p);
    if (phase !== expectedPhase) fail('LIVE_STAGE_ORDER');
    exact(p.binding, ['schemaVersion', 'runId', 'taskFingerprint', 'attempt', 'candidateFingerprint'], 'LIVE_BINDING_SCHEMA');
    const b = p.binding;
    if (b.schemaVersion !== 1 || typeof b.runId !== 'string' || b.runId.length !== 36 || !/^[a-f0-9-]{36}$/u.test(b.runId) ||
        b.taskFingerprint !== baseline.taskFingerprint || b.attempt !== attempt || b.candidateFingerprint !== candidateFingerprint ||
        (runId !== null && runId !== b.runId)) fail('LIVE_BINDING_MISMATCH');
    if (stableStringify(createTaskSpecification(p.task)) !== stableStringify(task)) fail('LIVE_TASK_MISMATCH');
    if (stableStringify(p.acceptanceCriteria) !== stableStringify(task.acceptanceCriteria)) fail('LIVE_CRITERIA_MISMATCH');
    if (candidateFingerprint !== null && createCandidate({ files: p.candidate.files }, { authorId: configuration.authorId }).fingerprint !== candidateFingerprint) fail('LIVE_CANDIDATE_MISMATCH');
    if (lifecycle().state !== 'IDLE') fail('LIVE_TRANSPORT_NOT_IDLE');
  }
  function event(stage, p, status, resultCandidateFingerprint, code = null) {
    if (events.length < 8) events.push(cloneFreeze({ stage, binding: p?.binding ?? null, status, resultCandidateFingerprint, code }));
  }
  const authorizeContext = Object.freeze({ authorize(raw) {
    const p = snapshotPayload(raw); guard(p, 'NEW', 0, null); runId = p.binding.runId; phase = 'AUTHORIZED';
    event('authorizeContext', p, 'PASS', null); return { status: 'PASS', evidence: { ...p.binding, reason: '' } };
  } });
  function draft(raw) {
    const p = snapshotPayload(raw); guard(p, 'AUTHORIZED', 0, null); phase = 'SEEDED';
    event('hostSeed', p, 'PASS', baseline.candidateFingerprint);
    return { candidate: { files: baseline.candidate.files.map(({ path, content }) => ({ path, content })) },
      evidence: { ...p.binding, candidateFingerprint: baseline.candidateFingerprint,
        note: 'Host-seeded source-reviewed baseline. No model draft occurred.' } };
  }
  async function invoke(raw, operation) {
    let p;
    try {
      p = snapshotPayload(raw);
      guard(p, operation === 'repair' ? 'SEEDED' : 'REPAIRED', 1,
        operation === 'repair' ? baseline.candidateFingerprint : repaired.candidateFingerprint);
      phase = operation === 'repair' ? 'REPAIRING' : 'REVIEWING';
      const { signal: _signal, ...data } = p;
      const role = operation === 'repair' ? 'author' : 'reviewer';
      const invocation = Object.freeze({ role, operation, payload: Object.freeze(data), index: invocations.length });
      // Do not retain potentially oversized stage text after a pre-fetch refusal.
      invocations.push(Object.freeze({ role, operation, binding: p.binding, payload: null }));
      pendingInvocations.set(role, invocation);
      let result;
      try { result = await (operation === 'repair' ? adapters.author.repair(p) : adapters.reviewer.review(p)); }
      finally { pendingInvocations.delete(role); }
      returnedResults.push(cloneFreeze({ operation, result }));
      scopeGuard(p);
      if (phase !== (operation === 'repair' ? 'REPAIRING' : 'REVIEWING')) fail('LIVE_STAGE_ORDER');
      const fingerprint = result.evidence.candidateFingerprint;
      if (operation === 'repair') {
        if (result.status === 'NO_CHANGE') {
          if (result.candidate !== null || fingerprint !== baseline.candidateFingerprint) fail('LIVE_REPAIR_NOT_REGISTERED');
        } else if (result.status !== 'REPAIRED' || !preparations.some(item => item.candidateFingerprint === fingerprint)) fail('LIVE_REPAIR_NOT_REGISTERED');
        if (result.evidence.baseCandidateFingerprint !== baseline.candidateFingerprint) fail('LIVE_REPAIR_NOT_REGISTERED');
      }
      event(operation, p, result.status, fingerprint);
      phase = operation === 'repair' ? (fingerprint === baseline.candidateFingerprint ? 'NO_PROGRESS' : 'REPAIRED') : 'REVIEWED';
      return result;
    } catch (e) {
      phase = 'FAILED'; stopOwners(); event(operation, p, 'UNAVAILABLE', null, errorCode(e)); throw e;
    }
  }
  const executionOwners = Object.freeze(['author', 'reviewer'].map(role => Object.freeze({ id: `model.${role}`,
    status: () => liveModelOwnerStatusV1(owners[role].status()),
    settled: () => owners[role].settled(), cancel: () => owners[role].stop() })));
  const lane = Object.freeze({ authorizeContext,
    author: Object.freeze({ id: configuration.authorId, draft, repair: p => invoke(p, 'repair') }),
    reviewers: Object.freeze([Object.freeze({ id: configuration.reviewerId, review: p => invoke(p, 'review') })]),
    revoke() { revoked = true; stopOwners(); },
    executionOwners: () => executionOwners,
    snapshot: () => cloneFreeze({ schemaVersion: 'nisi-reviewed-live-model-lane-v4', configuration, configurationFingerprint,
      approval, approvalFingerprint, runId, phase, revoked, baselineCandidateFingerprint: baseline.candidateFingerprint,
      repairedCandidateFingerprint: repaired.candidateFingerprint, events, returnedResults,
      authorReceipts: adapters.author.receipts(), reviewerReceipts: adapters.reviewer.receipts(),
      lifecycle: lifecycle(), remoteInferenceStopped: 'NOT_OBSERVED', authorizing: false }) });
  lanes.set(lane, { suite, preparations, treatment, invocations, requestObservations, executionOwners }); return lane;
}
// Callback-free identity discovery, before any live snapshot is inspected.
export function readIssuedLiveModelLaneIdentityV4(lane) {
  const state = lanes.get(lane); if (!state) fail('LIVE_LANE_NOT_ISSUED');
  return Object.freeze({ suite: state.suite, executionOwners: state.executionOwners });
}
export function readIssuedLiveModelLaneV4(lane) {
  const state = lanes.get(lane); if (!state) fail('LIVE_LANE_NOT_ISSUED');
  return Object.freeze({ suite: state.suite, preparations: state.preparations, treatment: state.treatment,
    invocations: Object.freeze([...state.invocations]), requestObservations: Object.freeze([...state.requestObservations]), snapshot: lane.snapshot() });
}

// PRIVATE V4 projection, not an execution entry point or admission grant.
// Only the arm owner starts operations; this module checks and projects data.
import { record } from '../../evaluation/intake-v1.mjs';
import { readScheduledPairedTrialIntentV1 } from '../../evaluation/paired-trial-runner-v1.mjs';
import { encodeRepositoryTrialCandidateV1 } from '../../evaluation/repository-trial-candidate-v1.mjs';
import { cloneFreeze,stableStringify,sha256Text } from '../../workflow/contracts.mjs';
import { createRepositoryLiveModelRunV4 } from '../../receipts/repository-live-model-run-v4.mjs';
import { readIssuedLiveModelLaneV4, prepareReviewedLiveModelLaneV4 } from './reviewed-live-model-v4.mjs';
import { describeRepairGuidancePolicyV1 } from './repair-guidance-policy-v1.mjs';

const fail = code => { throw Object.assign(Error(code),{code}); };
const hash = (domain,value) => sha256Text(domain+'\0'+stableStringify(value));
const same = (a,b) => stableStringify(a) === stableStringify(b);

export function describeRepositoryTrialInputsV2(lane) {
  const {preparations,treatment,snapshot} = readIssuedLiveModelLaneV4(lane), c = snapshot.configuration;
  return describePrepared(preparations,treatment,c);
}
// Prospective settings share the exact projection, but issue no execution
// identity. They cannot replace the original lane/intent checks below.
export function describePlannedRepositoryTrialInputsV2(input,transportKind='LOOPBACK_HTTP') {
  const {preparations,treatment,configuration}=prepareReviewedLiveModelLaneV4(input,transportKind);
  return describePrepared(preparations,treatment,configuration);
}
function describePrepared(preparations,treatment,c) {
  const policy = describeRepairGuidancePolicyV1(treatment);
  const configuration = cloneFreeze({schemaVersion:'nisi-repository-trial-configuration-v2',
    roles:{author:c.author,reviewer:c.reviewer},timeoutMs:c.timeoutMs,maxOutputTokens:c.maxOutputTokens,
    maxRequestBytes:c.maxRequestBytes,maxResponseBytes:c.maxResponseBytes,transportKind:c.transportKind,policy});
  const modelSettingsSha256 = hash('nisi/repository-trial-configuration/v2',configuration);
  return cloneFreeze({schemaVersion:'nisi-repository-trial-inputs-v2',
    model:'nisi-v4-composite:'+modelSettingsSha256,modelSettingsSha256,configuration,
    taskSha256:preparations[0].taskFingerprint,baselineSha256:preparations[0].baselineFingerprint,
    suiteFingerprint:c.suiteFingerprint,reviewedSourceFingerprint:c.reviewedSourceFingerprint,
    arm:c.arm,treatmentFingerprint:treatment.fingerprint,guidancePolicySha256:policy.sha256,
    taskDigestProfile:'nisi/workflow-task/v1',baselineDigestProfile:'nisi/repository-snapshot/v1',
    authorizing:false});
}

export function checkRepositoryTrialIntentV2(intent,lane) {
  const {profile} = readScheduledPairedTrialIntentV1(intent), inputs = describeRepositoryTrialInputsV2(lane);
  for (const key of ['model','modelSettingsSha256','taskSha256','baselineSha256','arm'])
    if (intent[key] !== inputs[key]) fail('TRIAL_V2_INTENT_BINDING');
  const expectedPolicy = {version:inputs.configuration.policy.version,sha256:inputs.guidancePolicySha256};
  if (!same(profile.trialPolicy,expectedPolicy) ||
      !same(intent.trialPolicy,intent.arm === 'ON' ? expectedPolicy : null) ||
      intent.policyMode !== (intent.arm === 'ON' ? 'ISOLATED_TRIAL' : 'OFF')) fail('TRIAL_V2_POLICY_BINDING');
  return inputs;
}

export function projectRepositoryTrialV2(input) {
  const {report,hostResult,lane,intent,description} = record(input,['report','hostResult','lane','intent','description']);
  if (!hostResult || Object.getOwnPropertyDescriptor(hostResult,'report')?.value !== report) fail('TRIAL_V2_REPORT_CHANNEL');
  const current = checkRepositoryTrialIntentV2(intent,lane);
  if (!same(description,current)) fail('TRIAL_V2_CONFIGURATION_CHANGED');
  const receipt = createRepositoryLiveModelRunV4({lane,hostResult});
  if (receipt.lane.revoked || receipt.lane.lifecycle.state !== 'IDLE' || receipt.lane.lifecycle.pendingTransports !== 0 ||
      receipt.lane.lifecycle.recoveryRequired || hostResult.state !== 'SETTLED') fail('TRIAL_V2_OWNER_UNCONFIRMED');
  if (report.candidate === null) fail('TRIAL_V2_CANDIDATE_MISSING');
  const encoded = encodeRepositoryTrialCandidateV1(report.candidate);
  if (encoded.candidateFingerprint !== receipt.finalCandidateFingerprint) fail('TRIAL_V2_CANDIDATE_BINDING');
  const noProgress = receipt.status === 'CONSISTENT_NO_PROGRESS';
  const counts = {author:1,reviewer:noProgress ? 0 : 1};
  const completeInventory = ['author','reviewer'].every(role => {
    const rows = receipt.lane[role+'Receipts'];
    return rows.length === counts[role] && rows.every(r=>r.status === 'RESPONSE_VALIDATED');
  });
  const synthetic = current.configuration.transportKind === 'INJECTED_TEST_TRANSPORT';
  const tokenUsage = !synthetic && completeInventory && receipt.usage.complete
    ? {input:receipt.usage.totals.promptTokens,output:receipt.usage.totals.completionTokens} : null;
  const modelCalls = !synthetic && completeInventory ? receipt.usage.calls : null;
  const executor = cloneFreeze({requestId:intent.requestId,profileSha256:intent.profileSha256,
    candidateText:encoded.candidateText,candidateSha256:encoded.candidateSha256,completionClaim:report.outcome === 'COMPLETED',
    tokenUsage,durationMs:null,repairAttempts:report.repairAttempts,modelCalls});
  const author = receipt.lane.authorReceipts[0];
  const identity = cloneFreeze({schemaVersion:'nisi-repository-trial-projection-v2',intent,inputs:current,
    repositoryRunId:report.runId,reportSha256:receipt.reportSha256,repositoryReceiptFingerprint:receipt.fingerprint,
    repositoryReceiptStatus:receipt.status,repositoryReceiptReasons:receipt.reasons,
    engineOutcome:report.outcome,workflowOutcome:report.workflowOutcome,
    completionClaim:executor.completionClaim,completionClaimSource:'ENGINE_OUTCOME_LABEL_COMPLETED_V1',
    candidate:{serializationProfile:encoded.serializationProfile,candidateFingerprint:encoded.candidateFingerprint,
      candidateSha256:encoded.candidateSha256,byteLength:encoded.byteLength},
    treatment:{arm:current.arm,treatmentFingerprint:current.treatmentFingerprint,policySha256:current.guidancePolicySha256,
      applicationPoint:current.configuration.policy.applicationPoint,requestInspection:receipt.requestInspection.status,
      localDispatch:author?.treatment.dispatch ?? 'NOT_OBSERVED',systemPromptSha256:author?.treatment.systemPromptSha256 ?? null,
      modelUseAttested:false,effectiveness:'NOT_MEASURED'},
    usage:{sourceKind:synthetic?'SYNTHETIC_FIXTURE':'VALIDATED_REPORTED_COUNTERS',completeInventory,reported:receipt.usage,
      projectedTokens:tokenUsage,projectedModelCalls:modelCalls,modelCallsMeaning:'VALIDATED_ROLE_RECEIPT_COUNT_NOT_PROVIDER_EXECUTION',
      hostSeedInference:false,durationMs:null,durationSource:'NOT_MEASURED'},
    oracleEvaluated:false,modelAuthenticityAttested:false,executionAttested:false,measurementVerified:false,
    causalClaim:false,authorizing:false,promotionEligible:false,resumable:false});
  return Object.freeze({executor,evidence:cloneFreeze({...identity,fingerprint:hash('nisi/repository-trial-projection/v2',identity)})});
}

